  const handleApproveCommit = useCallback(() => onApprove('commit'), [onApprove]);

  return (
    <div
      className="space-y-3 p-4 mx-3 mb-3 rounded-lg"
      style={{
        background: 'linear-gradient(135deg, rgba(185, 28, 28, 0.05) 0%, rgba(212, 160, 23, 0.03) 100%)',
