          <Info size={8} />
          Details
        </button>

        {agent.vote && (
          <>
            <span
              className="ml-auto"
              style={{
                fontSize: '8px',
                color: voteColor,
                fontFamily: 'var(--font-orbitron), sans-serif',
                fontWeight: 700,
